    "topologyYaml": "version: \"0.2\"\ngraph:\n  id: vscode-inspector-workflow\n  layers:\n    - id: access\n      labels:\n        name: Access\n    - id: security\n      labels:\n        name: Security\n    - id: annotations\n      labels:\n        name: Annotations\n  nodes:\n    - id: access-a\n      labels:\n        role: router\n        site: a\n        name: Access A\n      data:\n        status: ok\n        owner: network\n      layers: [access, security]\n      position: [180, 250]\n    - id: firewall\n      labels:\n        role: firewall\n        policy: inspect\n        name: Firewall\n      data:\n        status: active\n        revision: 12\n      layers: [security]\n      position: [420, 250]\n    - id: app\n      labels:\n        role: service\n        name: App\n      data:\n        status: active\n      layers: [access]\n      position: [660, 250]\n  links:\n    - id: access-a-firewall\n      source: access-a\n      target: firewall\n      labels:\n        layer: security\n        name: Access to firewall\n      layers: [security]\n    - id: firewall-app\n      source: firewall\n      target: app\n      labels:\n        layer: access\n        name: Firewall to app\n      layers: [access]\ndiagram:\n  callouts:\n    - id: inspector-note\n      title: Inspector\n      body: Edit name, layer, labels, data, and position.\n      target: firewall\n      size: [178, 70]\n      layers: [annotations]\nlayout:\n  mode: manual\n  width: 840\n  height: 500\n",
